10	// toLiveResultsDto is one: it reports the estimated provider cost and the
11	// model cost with its basis, and never claims zero spend for a live run. If
12	// this is ever null, deps.live is null whatever the environment says, so a
13	// live run can never spend money without a truthful mapper.
14	export const LIVE_RESULTS_MAPPER: ToResults | null = toLiveResultsDto;
15	
16	export function buildLiveDeps(
17	  config: LiveConfig,
18	  store: LiveStore,
19	  mapper: ToResults | null = LIVE_RESULTS_MAPPER,
20	): LiveDeps {
21	  return {
22	    store,
23	    hmacSecret: config.hmacSecret,
24	    live: mapper === null ? null : config.live,
25	    now: () => new Date(),
26	    ...realFactories,
27	    toResults: (result, ctx) => {
28	      if (ctx.mode === "synthetic") return toLiveResultsDto(result, ctx);
29	      if (mapper === null) throw new Error("no live results mapper");
30	      return mapper(result, ctx);
31	    },
32	  };
33	}
34	
35	interface Connected {
36	  readonly config: LiveConfig;
37	  readonly store: LiveStore;
38	}
39	
40	let connect: (() => Promise<Connected>) | null = null;
41	
42	async function connected(): Promise<Connected | null> {
43	  const read = readLiveConfig(process.env);
44	  if (!read.ok) return null;
45	  connect ??= createMemoizedConnector(async () => {
46	    const { store } = await connectStore(read.config.databaseUrl);
47	    return { config: read.config, store };
48	  });
49	  return connect();
50	}
51	
52	export const runtime: LiveRuntime = {
53	  async getDeps() {
54	    const c = await connected();
55	    return c === null ? null : buildLiveDeps(c.config, c.store);
56	  },
57	  async getStore() {
58	    return (await connected())?.store ?? null;
59	  },
60	};
