41	    const prevClose = close;
42	    close = async () => {
43	      await scoped.end();
44	      await prevClose();
45	    };
46	    // Applying the schema file is itself part of the test.
47	    await scoped.query(
48	      readFileSync(join(__dirname, "../../src/server/live/schema.sql"), "utf8"),
49	    );
50	    // And it must be idempotent.
51	    await scoped.query(
52	      readFileSync(join(__dirname, "../../src/server/live/schema.sql"), "utf8"),
53	    );
54	  });
55	
56	  afterAll(async () => {
57	    await close?.();
58	    await drop?.();
59	  });
60	
61	  it("applies the schema with live mode OFF by default", async () => {
62	    expect(await store.isLiveEnabled()).toBe(false);
63	    await store.setLiveEnabled(true);
64	    expect(await store.isLiveEnabled()).toBe(true);
65	  });
66	
67	  it("lets exactly one of 20 parallel reserveRun calls through", async () => {
68	    expect(await store.admin.createCode("race", 5, "race-hash")).toBe(true);
69	    const results = await Promise.all(
70	      Array.from({ length: 20 }, () => store.reserveRun("race-hash", T0, 300)),
