74	    expect(
75	      results.filter((r) => !r.ok && r.reason === "run_in_progress"),
76	    ).toHaveLength(19);
77	
78	    const w = winners[0];
79	    if (!w.ok) throw new Error("unreachable");
80	    expect(w.runsRemaining).toBe(4);
81	
